script:
(function () {
  'use strict';
  // A loan with an interest-only lead-in, a balloon and extra payments, all in one schedule.
  //   Monthly rate i = rate / 12; N = amortization years x 12 months.
  //   Interest-only months 1..p: payment = balance x i.
  //   From month p + 1: payment A = B_p x i / (1 - (1 + i)^-(N - p)) (B_p / (N - p) at 0%), where B_p is
  //   the balance when interest-only ends; A then stays fixed (extra payments shorten the loan).
  //   Extras (a monthly amount plus one-time amounts) go straight to principal after the payment.
  //   Balloon: whatever is owed after the regular payment in month 12 x balloon years is paid in full.
  // Checked in Node (scratchpad tests/w3b6_loans/enl.test.js): plain $250,000 at 6.9% over 30 years ->
  //   $1,646.50 a month and $342,740.12 interest (360 x P - L, matching an independent Python calculation); interest-only payment
  //   $250,000 x 0.069 / 12 = $1,437.50; after 24 interest-only months the payment equals the closed
  //   form over 336 months; the balloon after 10 years equals the closed-form remaining balance
  //   B(1+i)^k - A((1+i)^k - 1)/i; extra payments match an independent month-by-month loop; 0% rate
  //   gives zero interest; principal + interest + extras + balloon always add up to the loan amount.
  var MAX_ROWS = 24, rowCounter = 0, last = null;
  var DEFAULT_ROWS = [{ month: 36, amount: 10000 }];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var INPUT_CLASS = 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none';

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function parse(raw) {
    raw = String(raw === undefined || raw === null ? '' : raw).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function read(id) { return parse(el(id).value); }

  function payment(bal, i, n) { return i === 0 ? bal / n : bal * i / (1 - Math.pow(1 + i, -n)); }

  // opts: { loan, i, n, io, balloon (month, 0 = none), extras: {month: amount}, monthly }
  function simulate(o) {
    var bal = o.loan, rows = [], interestTotal = 0, ioPay = 0, amort = 0, balloonPay = 0, balloonMonth = 0, extraTotal = 0;
    var eps = Math.max(1e-7, o.loan * 1e-12);
    for (var k = 1; k <= o.n; k++) {
      var interest = bal * o.i, sched;
      if (k <= o.io) { sched = interest; if (k === 1) ioPay = sched; }
      else {
        if (!amort) amort = payment(bal, o.i, o.n - o.io);
        sched = Math.min(amort, bal + interest);
      }
      var principal = sched - interest;
      bal -= principal;
      var extra = Math.min(Math.max(0, bal), (o.monthly || 0) + ((o.extras && o.extras[k]) || 0));
      bal -= extra;
      if (bal < eps) bal = 0;
      var balloon = 0;
      if (bal > 0 && (k === o.balloon || k === o.n)) {
        balloon = bal; bal = 0;
        if (k === o.balloon) { balloonPay = balloon; balloonMonth = k; }
        else { principal += balloon; sched += balloon; balloon = 0; } // rounding remainder at the end of the term
      }
      interestTotal += interest; extraTotal += extra;
      rows.push({ k: k, payment: sched, interest: interest, principal: principal, extra: extra, balloon: balloon, balance: bal });
      if (bal === 0) break;
    }
    return { rows: rows, interest: interestTotal, ioPay: ioPay, amort: amort, balloon: balloonPay, balloonMonth: balloonMonth,
      months: rows.length, extra: extraTotal };
  }

  // ---- Extra payment rows (DOM methods only) ----
  function make(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }
  function numberField(id, label, value, affix, affixFirst, attrs) {
    var wrap = make('div'), lab = make('label', 'form-label', label), group = make('div', 'input-group'), input = make('input', INPUT_CLASS);
    lab.setAttribute('for', id);
    input.type = 'number'; input.id = id;
    Object.keys(attrs).forEach(function (k) { input.setAttribute(k, attrs[k]); });
    input.value = value === undefined || value === null ? '' : String(value);
    var a = make('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }
  function addRow(d) {
    var list = el('enlRows');
    if (list.querySelectorAll('[data-row]').length >= MAX_ROWS) return;
    rowCounter++;
    var id = rowCounter, row = make('div', 'rounded-xl border border-line p-4');
    row.setAttribute('data-row', String(id));
    var grid = make('div', 'grid grid-cols-[minmax(0,1fr)_minmax(0,1fr)_auto] items-end gap-3');
    grid.appendChild(numberField('enlM' + id, 'In month', d.month, '#', true, { min: '1', step: '1', inputmode: 'numeric' }));
    grid.appendChild(numberField('enlA' + id, 'Amount', d.amount, '$', true, { min: '0', step: '500', inputmode: 'decimal' }));
    var remove = make('button', 'button-secondary h-11 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () { row.remove(); refreshRows(); update(); });
    grid.appendChild(remove);
    row.appendChild(grid);
    list.appendChild(row);
    refreshRows();
  }
  function refreshRows() {
    var rows = el('enlRows').querySelectorAll('[data-row]');
    for (var i = 0; i < rows.length; i++) rows[i].querySelector('[data-remove]').setAttribute('aria-label', 'Remove extra payment ' + (i + 1));
    el('enlAdd').disabled = rows.length >= MAX_ROWS;
  }
  function readExtras(n) {
    var rows = el('enlRows').querySelectorAll('[data-row]'), extras = {}, err = '', count = 0;
    for (var i = 0; i < rows.length && !err; i++) {
      var id = rows[i].getAttribute('data-row'), label = 'Extra payment ' + (i + 1) + ': ';
      var rawM = String(el('enlM' + id).value).trim(), rawA = String(el('enlA' + id).value).trim();
      if (rawM === '' && rawA === '') continue;
      var m = parse(rawM), a = rawA === '' ? 0 : parse(rawA);
      if (isNaN(m) || m < 1 || m > n || m % 1 !== 0) err = label + 'enter a month from 1 to ' + n + '.';
      else if (isNaN(a) || a < 0 || a > 1e10) err = label + 'enter an amount of $0 or more.';
      else if (a > 0) { extras[m] = (extras[m] || 0) + a; count++; }
    }
    return { extras: extras, error: err, count: count };
  }

  // ---- Output ----
  function when(k) {
    var y = Math.floor((k - 1) / 12) + 1;
    return 'month ' + k + ' (year ' + y + ')';
  }
  function span(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + ' yr' + (y === 1 ? '' : 's'));
    if (m) parts.push(m + ' mo' + (m === 1 ? '' : 's'));
    return parts.join(' ') || '0 mos';
  }
  function payText(s, io) {
    if (io > 0 && s.months > io) return money.format(s.ioPay) + ', then ' + money.format(s.amort);
    if (io > 0) return money.format(s.ioPay) + ' (interest only)';
    return money.format(s.amort);
  }
  function renderSchedule() {
    var body = el('enlSchedule');
    if (!last) { body.innerHTML = ''; return; }
    var byYear = el('enlView').value === 'year', out = [], acc = null;
    setText('enlPeriodCol', byYear ? 'Year' : 'Month');
    last.rows.forEach(function (r, idx) {
      var key = byYear ? Math.floor((r.k - 1) / 12) + 1 : r.k;
      if (!acc || acc.key !== key) { if (acc) out.push(acc); acc = { key: key, payment: 0, interest: 0, principal: 0, extra: 0, balloon: 0, balance: 0 }; }
      acc.payment += r.payment; acc.interest += r.interest; acc.principal += r.principal; acc.extra += r.extra; acc.balloon += r.balloon; acc.balance = r.balance;
      if (idx === last.rows.length - 1) out.push(acc);
    });
    body.innerHTML = out.map(function (a) {
      return '<tr><td>' + a.key + '</td><td>' + money.format(a.payment) + '</td><td>' + money.format(a.interest) + '</td><td>' + money.format(a.principal) +
        '</td><td>' + (a.extra > 0 ? money.format(a.extra) : '–') + '</td><td>' + (a.balloon > 0 ? money.format(a.balloon) : '–') + '</td><td>' + money.format(a.balance) + '</td></tr>';
    }).join('');
  }
  function clear() {
    ['enlAmort', 'enlIOPay', 'enlBalloonPay', 'enlInterest', 'enlSummary'].forEach(function (id) { setText(id, '–'); });
    el('enlSteps').innerHTML = '';
    last = null;
    renderSchedule();
  }

  function update() {
    var loan = read('enlLoan'), rate = read('enlRate'), years = read('enlTerm');
    var ioRaw = String(el('enlIO').value).trim(), blRaw = String(el('enlBalloon').value).trim(), moRaw = String(el('enlMonthly').value).trim();
    var io = ioRaw === '' ? 0 : parse(ioRaw), bl = blRaw === '' ? 0 : parse(blRaw), monthly = moRaw === '' ? 0 : parse(moRaw);
    var err = el('enlError'), msg = '', ex = null, n = 0;
    if ([loan, rate, years].some(isNaN)) msg = 'Enter the loan amount, interest rate and amortization term.';
    else if (loan <= 0 || loan > 1e10) msg = 'Enter a loan amount above $0.';
    else if (rate < 0 || rate > 50) msg = 'Enter an interest rate from 0% to 50%.';
    else if (years < 1 || years > 40 || years % 1 !== 0) msg = 'Enter an amortization term of 1 to 40 whole years.';
    else {
      n = years * 12;
      if (isNaN(io) || io < 0 || io % 1 !== 0 || io >= n) msg = 'Enter an interest-only period of 0 to ' + (n - 1) + ' whole months.';
      else if (isNaN(bl) || bl < 0 || bl % 1 !== 0 || bl > years) msg = 'Enter a balloon of 0 (none) to ' + years + ' whole years.';
      else if (isNaN(monthly) || monthly < 0 || monthly > 1e10) msg = 'Enter an extra monthly amount of $0 or more.';
      else { ex = readExtras(n); msg = ex.error; }
    }
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { clear(); return; }

    var i = rate / 100 / 12, balloon = bl > 0 && bl < years ? bl * 12 : 0;
    var hasExtra = ex.count > 0 || monthly > 0;
    var base = { loan: loan, i: i, n: n, io: 0, balloon: 0, extras: null, monthly: 0 };
    var steps = [{ name: 'Plain loan', o: base }];
    if (io > 0) steps.push({ name: '+ ' + io + ' interest-only month' + (io === 1 ? '' : 's'), o: { loan: loan, i: i, n: n, io: io, balloon: 0, extras: null, monthly: 0 } });
    if (balloon) steps.push({ name: '+ balloon after ' + bl + ' yr' + (bl === 1 ? '' : 's'), o: { loan: loan, i: i, n: n, io: io, balloon: balloon, extras: null, monthly: 0 } });
    if (hasExtra) steps.push({ name: '+ extra payments', o: { loan: loan, i: i, n: n, io: io, balloon: balloon, extras: ex.extras, monthly: monthly } });
    var prevInt = null;
    steps.forEach(function (s) { s.r = simulate(s.o); });
    var mine = steps[steps.length - 1].r, noExtra = hasExtra ? steps[steps.length - 2].r : mine, plain = steps[0].r;
    last = mine;

    setText('enlAmort', mine.months > io ? money.format(mine.amort) : 'None');
    setText('enlIOPay', io > 0 ? money.format(mine.ioPay) : 'None');
    setText('enlBalloonPay', mine.balloon > 0 ? money.format(mine.balloon) : 'None');
    setText('enlInterest', money.format(mine.interest));

    var parts = [];
    if (io > 0) parts.push('You pay interest only (' + money.format(mine.ioPay) + (monthly > 0 ? ' plus your extra' : '') + ') for ' + io + ' month' + (io === 1 ? '' : 's') +
      (mine.months > io ? ', then ' + money.format(mine.amort) + ' a month.' : '.'));
    else parts.push('You pay ' + money.format(mine.amort) + ' a month.');
    if (mine.balloon > 0) parts.push('A balloon of ' + money.format(mine.balloon) + ' is due in ' + when(mine.balloonMonth) + '.');
    else if (balloon) parts.push('Your extra payments clear the loan before the balloon falls due.');
    parts.push('The loan is paid off in ' + span(mine.months) + '.');
    if (hasExtra) parts.push('Your extra payments of ' + money.format(mine.extra) + ' save ' + money.format(Math.max(0, noExtra.interest - mine.interest)) +
      ' in interest' + (noExtra.months > mine.months ? ' and end the loan ' + span(noExtra.months - mine.months) + ' sooner.' : '.'));
    var d = mine.interest - plain.interest;
    if (Math.abs(d) < 0.005) parts.push('That is the same interest as a plain ' + years + '-year loan.');
    else parts.push('Compared with a plain ' + years + '-year loan, you pay ' + money.format(Math.abs(d)) + (d < 0 ? ' less' : ' more') + ' interest' +
      (d < 0 && mine.balloon > 0 ? ', mainly because the balloon repays the balance early.' : '.'));
    setText('enlSummary', parts.join(' '));

    el('enlSteps').innerHTML = steps.map(function (s, idx) {
      var change = prevInt === null ? '–' : (s.r.interest >= prevInt ? '+' : '−') + money.format(Math.abs(s.r.interest - prevInt));
      prevInt = s.r.interest;
      return '<tr><th scope="row">' + s.name + '</th><td>' + payText(s.r, s.o.io) + '</td><td>' + (s.r.balloon > 0 ? money.format(s.r.balloon) : '–') +
        '</td><td>' + span(s.r.months) + '</td><td>' + money.format(s.r.interest) + '</td><td>' + (idx === 0 ? '–' : change) + '</td></tr>';
    }).join('');
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULT_ROWS.forEach(addRow);
    var form = el('enlForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('enlAdd').addEventListener('click', function () { addRow({ month: '', amount: '' }); update(); });
    el('enlView').addEventListener('change', renderSchedule);
    update();
  });
})();
